import{_ as t,o as e,c as l,a5 as i}from"./chunks/framework.CXroN2RO.js";const c=JSON.parse('{"title":"疑問から選ぶ読み順","description":"","frontmatter":{"title":"疑問から選ぶ読み順","study":{"source":"統合ガイド","status":"published","generated":true,"catalog":true,"section":"learning","format":"path","domain":"guide","collection":"questions","order":0,"summary":"整数・浮動小数点、文字コード、メモリ確保、起動、同期、ファイルI/Oとマッピング、アセットロード、DNS・TCP・HTTP・TLS通信、入力と描画、Webの疑問から本文をたどる。"}},"headers":[],"relativePath":"guide/learning-paths.md","filePath":"guide/learning-paths.md"}'),r={name:"guide/learning-paths.md"};function o(s,a,h,n,d,m){return e(),l("div",null,[...a[0]||(a[0]=[i('<div id="読み進め方" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="疑問から選ぶ読み順" tabindex="-1">疑問から選ぶ読み順 <a class="header-anchor" href="#疑問から選ぶ読み順" aria-label="Permalink to &quot;疑問から選ぶ読み順&quot;">​</a></h1><p>辞典を最初から順番に読む必要はありません。いまの疑問に関係する本文から選びます。</p><h2 id="整数はメモリにどう並ぶか" tabindex="-1">整数はメモリにどう並ぶか <a class="header-anchor" href="#整数はメモリにどう並ぶか" aria-label="Permalink to &quot;整数はメモリにどう並ぶか&quot;">​</a></h2><ol><li><a href="/study/data/integer-bits-and-bytes.html">整数をビット列・16進数・バイト列で読む</a>で、値、表記、符号の解釈、バイト順を分ける。</li><li><a href="/study/practice/data/integer-byte-observation.html">C++の整数・バイト列観察サンプル</a>で、型の幅と実メモリ、明示的なLE/BE形式を比較する。</li><li><a href="/study/runtime/cpp-internals/memory-layout.html">メモリレイアウトとアラインメント</a>で、オブジェクトを置く場所やパディングとの違いを調べる。</li></ol><h2 id="floatで小さな差が消えるのはなぜか" tabindex="-1">floatで小さな差が消えるのはなぜか <a class="header-anchor" href="#floatで小さな差が消えるのはなぜか" aria-label="Permalink to &quot;floatで小さな差が消えるのはなぜか&quot;">​</a></h2><ol><li><a href="/study/data/floating-point-spacing.html">floatが表せる値と丸め</a>で、binary32の有効精度、表現できる値の間隔、丸めを調べる。</li><li><a href="/study/practice/data/float-spacing-observation.html">C++のfloat観察サンプル</a>で、ビット表現、隣接値、2の冪の境界、epsilonの意味を確かめる。</li><li><a href="/study/math/rendering/transform.html">座標変換</a>と<a href="/study/math/rendering/camera.html">カメラ・深度</a>で、描画で数値の尺度を扱う場面へつなぐ。</li></ol><h2 id="floatを等しいと判定するには" tabindex="-1">floatを等しいと判定するには <a class="header-anchor" href="#floatを等しいと判定するには" aria-label="Permalink to &quot;floatを等しいと判定するには&quot;">​</a></h2><ol><li><a href="/study/math/floating-point-comparison.html">浮動小数点の比較と許容差</a>で、厳密な等値と近似一致、単位を持つ絶対許容差と無次元の相対許容差を分ける。</li><li><a href="/study/practice/math/float-comparison-observation.html">C++・C#の比較サンプル</a>で、境界・NaN・Inf・非推移性・保存時に失われた座標差を確かめる。</li><li>表現できる値の間隔から調べたい場合は<a href="/study/data/floating-point-spacing.html">floatの刻み幅</a>へ戻る。</li></ol><h2 id="文字はどのようにバイト列になるか" tabindex="-1">文字はどのようにバイト列になるか <a class="header-anchor" href="#文字はどのようにバイト列になるか" aria-label="Permalink to &quot;文字はどのようにバイト列になるか&quot;">​</a></h2><ol><li><a href="/study/data/unicode-and-encoding.html">Unicodeと文字コード</a>で、コードポイント、UTF-8／UTF-16のコード単位、バイト列を分ける。</li><li><a href="/study/practice/data/unicode-observation.html">C++・C#の文字列観察サンプル</a>で、日本語・絵文字・結合文字の表現と、長さの数え方を比べる。</li><li><a href="/study/data/integer-bits-and-bytes.html">整数とバイト列</a>のエンディアンと結び付け、ファイルやAPIの文字コードを確認する。</li></ol><h2 id="「確保する」と内部で何が起きるか" tabindex="-1">「確保する」と内部で何が起きるか <a class="header-anchor" href="#「確保する」と内部で何が起きるか" aria-label="Permalink to &quot;「確保する」と内部で何が起きるか&quot;">​</a></h2><ol><li><a href="/study/runtime/memory/storage-duration-and-lifetime.html">記憶域期間・スコープ・寿命</a>を区別する。</li><li><a href="/study/runtime/memory/allocation-journey.html">malloc/newの内部</a>で、空き領域の再利用、必要時のOS要求、構築・破棄を追う。</li><li><a href="/study/os/virtual-memory.html">仮想メモリ</a>で、アドレス空間、ページ、予約・コミット・常駐、ページフォルトを区別する。</li><li><a href="/study/practice/memory/windows-memory-observation.html">Windows/C++の観察サンプル</a>で、予約・コミット・初回書込み・解放を実際に分けて確かめる。</li><li><a href="/study/runtime/memory/allocators-and-pools.html">用途別アロケータ</a>、<a href="/study/runtime/memory/memory-bugs.html">メモリバグ</a>、<a href="/study/runtime/memory/cache-locality-aos-soa.html">キャッシュ局所性</a>へ進む。</li></ol><h2 id="ソースコードがcpuで動くまで" tabindex="-1">ソースコードがCPUで動くまで <a class="header-anchor" href="#ソースコードがcpuで動くまで" aria-label="Permalink to &quot;ソースコードがCPUで動くまで&quot;">​</a></h2><ol><li><a href="/study/runtime/cpp-internals/build-pipeline-journey.html">ビルドの旅</a>でコンパイルとリンクをたどる。</li><li><a href="/study/runtime/cpp-internals/translation-units-and-headers.html">翻訳単位・ヘッダー</a>、<a href="/study/runtime/cpp-internals/symbols-and-linkage.html">シンボル・ABI</a>、<a href="/study/runtime/cpp-internals/object-files-and-libraries.html">実行ファイル・ライブラリ</a>を調べる。</li><li><a href="/study/os/process-startup.html">実行ファイルを起動してmainへ到達するまで</a>で、プロセス・スレッド、ローダー、CRTの役割を分ける。</li><li><a href="/study/practice/process/windows-process-observation.html">Windows/C++のプロセス観察</a>で、main前の記録、親子プロセス、ワーカースレッドのPID・TIDを確かめる。</li><li><a href="/study/runtime/cpp-internals/function-calls-and-cpu.html">関数呼び出し・レジスタ</a>へ進む。</li></ol><h2 id="スレッド間でデータを安全に共有するには" tabindex="-1">スレッド間でデータを安全に共有するには <a class="header-anchor" href="#スレッド間でデータを安全に共有するには" aria-label="Permalink to &quot;スレッド間でデータを安全に共有するには&quot;">​</a></h2><ol><li><a href="/study/runtime/thread-synchronization.html">スレッドと同期</a>で、共有状態と不変条件、同じロックで守る範囲、データを受け渡す順序を調べる。</li><li><a href="/study/practice/threads/inventory-synchronization.html">C++・C#の在庫消費サンプル</a>で、確認と消費、Snapshot、終了待ちと寿命を確かめる。</li><li><a href="/study/runtime/memory/concurrency-bugs.html">並行処理のバグ</a>で、データ競合・競合状態・false sharingの違いを調べる。</li></ol><h2 id="ファイルを読むと内部で何が起きるか" tabindex="-1">ファイルを読むと内部で何が起きるか <a class="header-anchor" href="#ファイルを読むと内部で何が起きるか" aria-label="Permalink to &quot;ファイルを読むと内部で何が起きるか&quot;">​</a></h2><ol><li><a href="/study/os/file-read-journey.html">ファイルを読む仕組み</a>で、アプリのバッファ、OSのファイルキャッシュ、ストレージへの要求を分ける。</li><li><a href="/study/practice/io/file-read-observation.html">C++・C#の読み取り観察</a>で、要求数と実読取数、ファイル位置、EOF、seek、失敗を確かめる。</li><li>テキストとして解釈するときは<a href="/study/data/unicode-and-encoding.html">Unicodeと文字コード</a>へ進む。</li></ol><h2 id="i-oの完了を待ちながら、別の処理を進めるには" tabindex="-1">I/Oの完了を待ちながら、別の処理を進めるには <a class="header-anchor" href="#i-oの完了を待ちながら、別の処理を進めるには" aria-label="Permalink to &quot;I/Oの完了を待ちながら、別の処理を進めるには&quot;">​</a></h2><ol><li><a href="/study/os/asynchronous-file-io.html">非同期I/O</a>で、要求の発行と完了、即時完了、待機と継続、バッファの寿命を分ける。</li><li><a href="/study/practice/io/async-file-read-observation.html">C++・C#の同期・非同期比較</a>で、同じファイルを読み、完了結果と内容の一致を確かめる。</li><li>複数の処理から状態を共有するときは<a href="/study/runtime/thread-synchronization.html">スレッドと同期</a>も確認する。</li></ol><h2 id="ファイルをメモリへのアクセスとして読むには" tabindex="-1">ファイルをメモリへのアクセスとして読むには <a class="header-anchor" href="#ファイルをメモリへのアクセスとして読むには" aria-label="Permalink to &quot;ファイルをメモリへのアクセスとして読むには&quot;">​</a></h2><ol><li><a href="/study/os/memory-mapped-files.html">メモリマップドファイル</a>で、ファイル内位置と仮想アドレス、ページフォルト、ビューの寿命を分ける。</li><li><a href="/study/practice/io/mapped-file-observation.html">C++・C#の読み取り専用マッピング</a>で、通常のreadと内容を照合し、整列した位置と使いたい範囲の対応を確かめる。</li><li>アドレス変換の基礎は<a href="/study/os/virtual-memory.html">仮想メモリ</a>、実行時の組立ては<a href="/study/game/asset-loading.html">アセットロード設計</a>へ進む。</li></ol><h2 id="アセットが読み終わってから、ゲームで使えるまで" tabindex="-1">アセットが読み終わってから、ゲームで使えるまで <a class="header-anchor" href="#アセットが読み終わってから、ゲームで使えるまで" aria-label="Permalink to &quot;アセットが読み終わってから、ゲームで使えるまで&quot;">​</a></h2><ol><li><a href="/study/game/asset-loading.html">アセットロード設計</a>で、読み取り、展開・検証、登録、利用可能化、解放を分ける。</li><li><a href="/study/practice/assets/asset-lifecycle-model.html">C++・C#の状態と寿命のモデル</a>で、古い要求の完了、キャンセル、失敗を含む所有権の移動を確かめる。</li><li>実I/Oの完了待ちは<a href="/study/os/asynchronous-file-io.html">非同期I/O</a>、共有するキューや状態の保護は<a href="/study/runtime/thread-synchronization.html">スレッドと同期</a>も確認する。</li></ol><h2 id="入力からゲーム画面まで" tabindex="-1">入力からゲーム画面まで <a class="header-anchor" href="#入力からゲーム画面まで" aria-label="Permalink to &quot;入力からゲーム画面まで&quot;">​</a></h2><ol><li><a href="/study/game/patterns/game-loop-and-update.html">ゲームループ</a>で入力・更新・描画の時間を分ける。</li><li><a href="/study/game/ecs.html">ECS</a>でID、データ配置、Query、構成変更を調べる。</li><li><a href="/study/math/rendering/transform.html">座標変換</a>と<a href="/study/graphics/pipeline/overview.html">描画パイプライン</a>から画面へつなぐ。</li><li>作って試すなら<a href="/study/game/shooter-design.html">シューティングの設計</a>を読み、<a href="/study/game/shooter-cpp.html">C++版</a>または<a href="/study/game/shooter-unity.html">Unity版</a>へ進む。</li></ol><h2 id="sendしたデータが、相手のアプリへ届くまで" tabindex="-1">sendしたデータが、相手のアプリへ届くまで <a class="header-anchor" href="#sendしたデータが、相手のアプリへ届くまで" aria-label="Permalink to &quot;sendしたデータが、相手のアプリへ届くまで&quot;">​</a></h2><ol><li><a href="/study/network/tcp-sockets.html">ソケットとTCP通信</a>で、IP・ポート、送受信バッファ、バイト列とメッセージ、半閉鎖を分ける。</li><li><a href="/study/practice/network/tcp-loopback-observation.html">C++・C#のローカル通信</a>で、長さ付きメッセージを復元し、送信停止後の応答と受信EOFを確かめる。</li><li>待機と非同期処理の基本は<a href="/study/os/asynchronous-file-io.html">非同期I/O</a>へ進む。今回の通信例は、非ブロッキング操作とreadiness待ちを使う。</li></ol><h2 id="tcpのバイト列が、webの要求と応答になるまで" tabindex="-1">TCPのバイト列が、Webの要求と応答になるまで <a class="header-anchor" href="#tcpのバイト列が、webの要求と応答になるまで" aria-label="Permalink to &quot;TCPのバイト列が、Webの要求と応答になるまで&quot;">​</a></h2><ol><li><a href="/study/network/http-messages.html">HTTP通信</a>で、要求行、状態コード、ヘッダー、本文の形式と長さを分ける。</li><li><a href="/study/practice/network/http-message-observation.html">C++・C#のHTTP観察</a>で、ローカルのGETと応答を照合し、本文のバイト数と文字数、メッセージ完成とEOFを確かめる。</li><li>下の層から調べる場合は<a href="/study/network/tcp-sockets.html">TCPとソケット</a>、文字の表現は<a href="/study/data/unicode-and-encoding.html">Unicodeと文字コード</a>へ戻る。</li></ol><h2 id="名前から、接続先のip候補が決まるまで" tabindex="-1">名前から、接続先のIP候補が決まるまで <a class="header-anchor" href="#名前から、接続先のip候補が決まるまで" aria-label="Permalink to &quot;名前から、接続先のIP候補が決まるまで&quot;">​</a></h2><ol><li><a href="/study/network/dns-resolution.html">DNSと名前解決</a>で、OSの名前解決、再帰リゾルバー、権威DNS、レコードとキャッシュを分ける。</li><li><a href="/study/practice/network/name-resolution-observation.html">C++・C#の名前解決観察</a>で、数値IP・localhost・追加指定する公開名を調べ、APIの結果から分かる範囲を確かめる。</li><li>IPを得た後の接続は<a href="/study/network/tcp-sockets.html">TCPとソケット</a>、要求と応答は<a href="/study/network/http-messages.html">HTTP通信</a>へ進む。</li></ol><h2 id="httpsで暗号化し、接続相手を確かめるには" tabindex="-1">HTTPSで暗号化し、接続相手を確かめるには <a class="header-anchor" href="#httpsで暗号化し、接続相手を確かめるには" aria-label="Permalink to &quot;HTTPSで暗号化し、接続相手を確かめるには&quot;">​</a></h2><ol><li><a href="/study/network/tls-https.html">TLS・証明書・HTTPS</a>で、鍵共有、証明書、相手名の検証、暗号化したHTTPの関係を調べる。</li><li><a href="/study/practice/network/https-observation.html">C++・C#のHTTPS観察</a>で、標準の証明書検証を保ち、APIが返す接続情報とHTTP応答を確かめる。</li><li>接続先の候補は<a href="/study/network/dns-resolution.html">DNSと名前解決</a>、要求の意味は<a href="/study/network/http-messages.html">HTTP通信</a>で確認する。</li></ol><h2 id="urlを開いてからページが見えるまで" tabindex="-1">URLを開いてからページが見えるまで <a class="header-anchor" href="#urlを開いてからページが見えるまで" aria-label="Permalink to &quot;URLを開いてからページが見えるまで&quot;">​</a></h2><ol><li>通信は<a href="/study/network/dns-resolution.html">DNSと名前解決</a>、<a href="/study/network/tcp-sockets.html">TCPとソケット</a>、<a href="/study/network/http-messages.html">HTTPの要求と応答</a>、<a href="/study/network/tls-https.html">TLS・証明書・HTTPS</a>で調べる。</li><li><a href="/study/browser/rendering-journey.html">ブラウザの描画</a>で、受信したHTMLからDOM、スタイル、レイアウト、描画、合成までをつなぐ。</li><li><a href="/study/practice/browser/render-observation.html">DOMと描画の変化を観察する</a>で、幅・色・移動・透明度を変え、寸法APIとrAFで確認できる範囲を試す。</li></ol><h2 id="作り方の変化を歴史から見る" tabindex="-1">作り方の変化を歴史から見る <a class="header-anchor" href="#作り方の変化を歴史から見る" aria-label="Permalink to &quot;作り方の変化を歴史から見る&quot;">​</a></h2><p><a href="/study/history/video-games.html">ビデオゲーム史</a>の作品・ハード・媒体・流通と、<a href="/study/guide/rendering/timeline.html">リアルタイム3D技術史</a>の技術の変化から、気になった仕組みへ進みます。</p>',39)])])}const f=t(r,[["render",o]]);export{c as __pageData,f as default};
